-- GUARD 1 — the decision table arrived whole.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM mig1918_decisions;
  IF n <> 228 THEN
    RAISE EXCEPTION 'migration 1918: expected 228 decisions, found %', n;
  END IF;
  SELECT count(*) INTO n FROM (SELECT DISTINCT politician_id, topic_id FROM mig1918_decisions) s;
  IF n <> 228 THEN
    RAISE EXCEPTION 'migration 1918: decisions contain duplicate (politician, topic) pairs; % distinct of 228', n;
  END IF;
END $$;

-- GUARD 2 — every target must TODAY carry a non-zero chair somewhere. If a pair is already blank,
-- something else has moved it since the queue was measured and this file is operating on a stale
-- picture; stop rather than silently re-blank it.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1918_decisions d
   WHERE NOT EXISTS (
     SELECT 1 FROM inform.politician_answers pa
      WHERE pa.politician_id = d.politician_id
        AND pa.topic_id = d.topic_id
        AND pa.value <> 0);
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1918: % target pair(s) no longer carry a non-zero chair — re-measure the queue', n;
  END IF;
END $$;

-- GUARD 3 — every target must have citations available to carry forward, BEFORE anything is
-- written. 🔴 Migration 1915 wrote 206 blanks with EMPTY sources and every ROW COUNT passed; the
-- defect was in the SHAPE of what was written, not in how much. Checking first means the
-- transaction aborts instead of producing undocumented blanks.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1918_decisions d
   WHERE NOT EXISTS (
     SELECT 1 FROM inform.politician_context pc0
      WHERE pc0.politician_id = d.politician_id
        AND pc0.topic_id = d.topic_id
        AND coalesce(cardinality(pc0.sources), 0) > 0);
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1918: % target pair(s) have no citations to carry forward', n;
  END IF;
END $$;

-- The answer: 0 is the documented blank.
INSERT INTO inform.politician_answers
  (politician_id, topic_id, value, season_id, topic_revision_id)
SELECT d.politician_id, d.topic_id, 0, '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid, d.topic_revision_id
  FROM mig1918_decisions d
ON CONFLICT (politician_id, topic_id, season_id) DO UPDATE
  SET value = 0, updated_at = now();

-- The record of WHY, which is what makes it a documented blank rather than a deletion.
-- 🔑 SOURCES ARE CARRIED FROM THE ROW BEING WITHDRAWN, by the SQL rather than from the decision
-- table, so they cannot drift from what the pair actually cites.
-- ⚠ On conflict, `sources` is deliberately NOT overwritten: a row that already exists in Season 2
-- carries its own citations, and those are the right ones to keep.
INSERT INTO inform.politician_context
  (politician_id, topic_id, reasoning, sources, season_id, topic_revision_id)
SELECT d.politician_id, d.topic_id, d.reasoning,
       COALESCE((SELECT pc0.sources
                   FROM inform.politician_context pc0
                  WHERE pc0.politician_id = d.politician_id
                    AND pc0.topic_id = d.topic_id
                    AND coalesce(cardinality(pc0.sources), 0) > 0
                  ORDER BY (pc0.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid), pc0.updated_at DESC NULLS LAST
                  LIMIT 1), '{}'::text[]),
       '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid, d.topic_revision_id
  FROM mig1918_decisions d
ON CONFLICT (politician_id, topic_id, season_id) DO UPDATE
  SET reasoning = EXCLUDED.reasoning,
      sources   = CASE WHEN coalesce(cardinality(inform.politician_context.sources), 0) = 0
                       THEN EXCLUDED.sources
                       ELSE inform.politician_context.sources END,
      updated_at = now();

-- GUARD 4 — verify the RESULT, not the absence of an error.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1918_decisions d
    JOIN inform.politician_answers pa
      ON pa.politician_id = d.politician_id AND pa.topic_id = d.topic_id
     AND pa.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid AND pa.value = 0
    JOIN inform.politician_context pc
      ON pc.politician_id = d.politician_id AND pc.topic_id = d.topic_id
     AND pc.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid
     AND pc.reasoning LIKE 'INTERNAL RECORD%';
  IF n <> 228 THEN
    RAISE EXCEPTION 'migration 1918: expected 228 blanked Season 2 rows, found %', n;
  END IF;

  SELECT count(*) INTO n
    FROM mig1918_decisions d
    JOIN inform.politician_context pc
      ON pc.politician_id = d.politician_id AND pc.topic_id = d.topic_id
     AND pc.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid
   WHERE coalesce(cardinality(pc.sources), 0) = 0;
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1918: % blank(s) carry no citations - a documented blank must record what was checked', n;
  END IF;

  -- Each row must say WHICH KIND of nothing it is: the reason code is part of the record.
  SELECT count(*) INTO n
    FROM mig1918_decisions d
    JOIN inform.politician_context pc
      ON pc.politician_id = d.politician_id AND pc.topic_id = d.topic_id
     AND pc.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid
   WHERE pc.reasoning NOT LIKE '%Shape:%';
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1918: % blank(s) do not record which kind of nothing they are', n;
  END IF;

  SELECT count(*) INTO n
    FROM inform.politician_answers pa
    JOIN inform.seasons s ON s.id = pa.season_id AND s.name = 'Season 1'
    JOIN mig1918_decisions d
      ON d.politician_id = pa.politician_id AND d.topic_id = pa.topic_id
   WHERE pa.value = 0;
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1918: % Season 1 answer(s) were modified — Season 1 is closed', n;
  END IF;

  -- The 37 KEEPs must be untouched. None of them appears in the decision table, so the only way
  -- one could have moved is a bug in how the table was built.
  SELECT count(*) INTO n FROM mig1918_decisions d
   WHERE d.ledger_no = ANY (ARRAY['M012','M014','M023','M035','M037','M038','M047','M049','M050','M051','M052','M062','M063','M068','M069','M072','M073','M075','M080','M090','M092','M094','M096','M097','M098','M106','M107','M113','M116','M119','M122','M123','M125','M127','M128','M130','M131','M133','M134','M135','M138','M141','M143','M146','M147','M151','M152','M153','M158','M159','M160','M163','M164','M166','M167','M169','M175','M181','M185','M187','M188','M189','M195','M201','M204','M207','M209','M213','M215','M216','M219','M222','M224','M226','M227','M229','M231','M233','M234','M235','M244','M248','M250','M251','M256','M259','M260','M261','M264','M265','M268','M269','M271','M273','M274','M280','M283','M284','M286','M288','M289','M293','M297','M298','M299','M304','M305','M306','M307','M311','M312','M313','M317','M318','M319','M322','M325','M326','M329','M330','M331','M334','M335','M336','M339','M340','M341','M343','M348','M349','M350','M351']);
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1918: % row(s) adjudicated KEEP appear in the blank set', n;
  END IF;
END $$;
